function countValidWords(sentence: string): number {
    const check = (s: string): number => {
        if (s.length === 0) {
            return 0;
        }
        let st = false;
        for (let i = 0; i < s.length; ++i) {
            if (/\d/.test(s[i])) {
                return 0;
            }
            if (['!', '.', ','].includes(s[i]) && i < s.length - 1) {
                return 0;
            }
            if (s[i] === '-') {
                if (st || [0, s.length - 1].includes(i)) {
                    return 0;
                }
                if (!/[a-zA-Z]/.test(s[i - 1]) || !/[a-zA-Z]/.test(s[i + 1])) {
                    return 0;
                }
                st = true;
            }
        }
        return 1;
    };
    return sentence.split(/\s+/).reduce((acc, s) => acc + check(s), 0);
}

class Solution(object):
    def countValidWords(self, sentence):
        """
        :type sentence: str
        :rtype: int
        """
        ans = 0
        for token in sentence.split():
            is_valid = True
            hyphen_cnt = 0
            for i, c in enumerate(token):
                if c.isdigit():
                    is_valid = False
                    break
                if c == '-':
                    if hyphen_cnt != 0:
                        is_valid = False
                        break
                    if i == 0 or i == len(token) - 1 or not token[i - 1].isalpha() or not token[i + 1].isalpha():
                        is_valid = False
                        break
                    hyphen_cnt += 1
                if c == '!' or c == '.' or c == ',':
                    if i != len(token) - 1:
                        is_valid = False
                        break
            ans += int(is_valid)
        return ans
